#include "stdlib/stats/base/dists/gumbel/skewness.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/sqrt.h"
#include "stdlib/constants/float64/pi.h"
#include "stdlib/constants/float64/pi_squared.h"
#include "stdlib/math/base/special/riemann_zeta.h"

static const double SQRT6 = 2.449489742783178; // sqrt(6)
static const double ZETA3 = 1.2020569031595951; // ζ(3)
static const double PI_CUBED = 31.0062766802998201754763150671013; // π^3

/**
* Returns the skewness for a Gumbel distribution with location `mu` and scale `beta`.
*
* @param mu      location parameter
* @param beta    scale parameter
* @return        skewness
*
* @example
* double y = stdlib_base_gumbel_skewness( 0.0, 1.0 );
* // returns ~1.14
*/
double stdlib_base_dists_gumbel_skewness( const double mu, const double beta ) {
	if (
		stdlib_base_is_nan( mu ) ||
		stdlib_base_is_nan( beta ) ||
		beta <= 0.0
	) {
		return 0.0/0.0; // NaN
	}
	// return 1.1395470994046495;
	return ( 12.0 * SQRT6 * ZETA3 ) / PI_CUBED;
}
